files=sorted({f for r in rows for f in r['files']})
receipts=[]
for rp in sorted((P/'receipts').rglob('receipt.json')):
 try: j=json.loads(rp.read_text())
 except Exception: continue
 hits=[]
 for key in ['files','artifacts','sha256']:
  d=j.get(key,{})
  if not isinstance(d,dict): continue
  for k,v in d.items():
   if k in files and isinstance(v,str): hits.append(dict(source=k,recorded_sha256=v,current_sha256=sha(P/k),matches=v==sha(P/k)))
 if hits: receipts.append(dict(path=str(rp.relative_to(REPO)),sha256=sha(rp),status=j.get('status'),kernel_check=j.get('kernel_check',j.get('flags')),source_matches=hits))
source=[]
for f in files:
 t=(P/f).read_text(); ds=[]
 for i,l in enumerate(t.splitlines(),1):
  m=re.search(r'\b(?:def|theorem|lemma|instance)\s+([A-Za-z_][A-Za-z0-9_]*)',l)
  if m:ds.append(dict(name=m.group(1),line=i))
 source.append(dict(path=str((P/f).relative_to(REPO)),sha256=sha(P/f),lines=len(t.splitlines()),declaration_locators=ds,historical_exact_receipts=[r['path'] for r in receipts if any(h['source']==f and h['matches'] for h in r['source_matches'])]))
prose=[]
for n in ['intrinsic-affine-comparison','intrinsic-open-restriction','intrinsic-hodge-domain','intrinsic-global-gluing','tensor-foundation','completed-contact-normalization']:
 f=P/'receipts'/n/'README.md';prose.append(dict(path=str(f.relative_to(REPO)),sha256=sha(f)))
head=subprocess.check_output(['git','-C',str(REPO),'rev-parse','HEAD'],text=True).strip()
dump(OUT/'inventory.json',dict(scope='Retrospective bounded audit of already-published intrinsic differential/Hodge and tensor equivalences. Map families, not an exhaustive repository count.',repo_commit=head,claim_families=rows))
dump(OUT/'source-manifest.json',dict(repo_commit=head,reviewed_files=source,read_prose=prose,historical_receipts=receipts,verification_note='Source hashes were compared to retained historical strict-replay receipts. No Lean replay was run for this audit; no whole-dependency independent review is claimed.'))
checks=[dict(check='reviewed source has exact retained receipt',source=s['path'],pass_=bool(s['historical_exact_receipts'])) for s in source]
checks += [dict(check='all selected historical source hashes match',receipt=r['path'],pass_=all(h['matches'] for h in r['source_matches'])) for r in receipts]
# Explicit declarations are the essential binding. Generic interface descriptions stay prose.
for row in rows:
 for name in row['maps']:
  ns,decl=name.rsplit('.',1)
  f=P/(ns+'.lean')
  checks.append(dict(check='named map declaration exists',name=name,pass_=bool(re.search(r'\b(?:def|theorem|lemma|instance)\s+'+re.escape(decl)+r'\b',f.read_text()))))
dump(OUT/'binding-check.json',dict(status='PASS' if all(x['pass_'] for x in checks) else 'REQUIRES_REVIEW',checks=checks,mathematical_certification=False,note='Checks source/evidence identity and named declaration existence only. Mathematical assessment is the separate report.'))
print(json.dumps({'commit':head,'families':len(rows),'files':len(files),'receipt_records':len(receipts),'checks':len(checks),'failed':[x for x in checks if not x['pass_']]},indent=2))
